-- =============================================================================
-- BVC EVENT ATTENDANCE SYSTEM — PHASE 1 SYSTEM SEED (PART 1)
-- Matched to exact Supabase Schema
-- =============================================================================

CREATE TABLE IF NOT EXISTS roles (
    role_id VARCHAR(50) PRIMARY KEY,
    role_name VARCHAR(100) NOT NULL UNIQUE,
    description TEXT,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

ON CONFLICT (role_id) DO NOTHING;

CREATE TABLE IF NOT EXISTS department_hods (
    id VARCHAR(50) PRIMARY KEY,
    department_id VARCHAR(50) NOT NULL REFERENCES departments(department_id) ON DELETE CASCADE,
    user_id VARCHAR(50) NOT NULL REFERENCES users(user_id) ON DELETE CASCADE,
    assigned_at TIMESTAMPTZ DEFAULT NOW(),
    UNIQUE(department_id, user_id)
);

CREATE TABLE IF NOT EXISTS event_assignments (
    assignment_id VARCHAR(50) PRIMARY KEY,
    event_id VARCHAR(50) NOT NULL REFERENCES events(event_id) ON DELETE CASCADE,
    user_id VARCHAR(50) NOT NULL REFERENCES users(user_id) ON DELETE CASCADE,
    role VARCHAR(50) NOT NULL,
    coordinator_type VARCHAR(50) DEFAULT 'N/A',
    status VARCHAR(20) DEFAULT 'Active',
    assigned_by VARCHAR(50) REFERENCES users(user_id),
    assigned_at TIMESTAMPTZ DEFAULT NOW(),
    UNIQUE(event_id, user_id, role)
);

-- Ensure users table has default_role column for dynamic resolution
ALTER TABLE IF EXISTS users ADD COLUMN IF NOT EXISTS default_role VARCHAR(50) DEFAULT 'Coordinator';

-- DEPARTMENTS (11 Records)
ON CONFLICT (department_code) DO UPDATE SET 
  department_id = EXCLUDED.department_id,
  department_name = EXCLUDED.department_name;

-- USERS (150 Master Accounts)
ON CONFLICT (user_id) DO UPDATE SET username = EXCLUDED.username;

-- DEPARTMENT HODs (Multi-HOD Junction Mappings)
ON CONFLICT (id) DO NOTHING;

-- EVENTS (25 Production Events)
ON CONFLICT (event_id) DO NOTHING;

-- EVENT ASSIGNMENTS (Multi-Role Event Level Assignments)
ON CONFLICT (assignment_id) DO NOTHING;
